// Vérifie le secret (en-tête X-Documenso-Secret) puis extrait l'essentiel.
// Payload Documenso : { event: 'DOCUMENT_COMPLETED', payload: { title, recipients: [{ email, name }] } }
const headers = $json.headers || {};
const provided = headers['x-documenso-secret'] || headers['X-Documenso-Secret'] || '';
const expected = $env.ALPHA_DOCUMENSO_SECRET || '';
if (expected && provided !== expected) {
  throw new Error('Secret Documenso invalide — webhook rejeté.');
}
const b = $json.body || {};
const event = String(b.event || b.type || '').toUpperCase();
if (!event.includes('COMPLETED') && !event.includes('SIGNED')) {
  return []; // autre événement (créé, ouvert…) → rien à faire
}
const p = b.payload || b.data || b;
const recipients = p.recipients || p.Recipient || [];
const first = Array.isArray(recipients) ? recipients[0] || {} : recipients;
const email = String(first.email || p.email || '').toLowerCase().trim();
const name = String(first.name || p.name || '');
const title = String(p.title || p.documentName || 'contrat');
if (!email) return [];
return [{ json: { email, name, title } }];
